(function(){'use strict';
const KEY='nawaf-hq-v5';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const ICONS={search:'M11 4a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 5 5',dashboard:'M3 3h7v7H3V3zm11 0h7v4h-7V3zM3 14h7v7H3v-7zm11-3h7v10h-7V11z',workforce:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8m13 10v-2a4 4 0 0 0-3-3.87m-2-11.96a4 4 0 0 1 0 7.75',projects:'M3 5h7l2 2h9v12H3V5z',tasks:'M9 11l3 3L22 4M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11',reports:'M5 3h14v18H5V3zm3 4h8M8 11h8M8 15h5',finance:'M3 18h18M6 15V9m6 6V5m6 10v-4M4 5l5 3 4-5 7 4',bolt:'M13 2 4 14h7l-1 8 9-12h-7l1-8z',apps:'M4 4h6v6H4V4zm10 0h6v6h-6V4zM4 14h6v6H4v-6zm10 0h6v6h-6v-6z'};
function svg(n){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[n]||ICONS.search}"/></svg>`}
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
let health={api:false,cloud:false,online:navigator.onLine,lastCheck:0};
function healthEl(){let h=$('.v11-health');if(h)return h;h=document.createElement('div');h.className='v11-health';h.innerHTML='<span class="dot"></span><button type="button" data-v11-health>فحص النظام</button><span class="v11-health-detail">جاري التحقق...</span>';document.body.appendChild(h);h.addEventListener('click',()=>checkHealth(true));return h}
function renderHealth(){const h=healthEl(),detail=h.querySelector('.v11-health-detail');let state='ok',label='النظام متصل';if(!health.online){state='bad';label='أوفلاين'}else if(!health.api||!health.cloud){state='warn';label='اتصال جزئي'}h.dataset.state=state;detail.textContent=`${label} • ${health.cloud?'السحابة متصلة':'السحابة غير متاحة'}`;h.querySelector('button').textContent=label}
async function checkHealth(force){if(!force&&Date.now()-health.lastCheck<15000)return;health.lastCheck=Date.now();health.online=navigator.onLine;try{const r=await fetch('/api/health',{cache:'no-store',signal:AbortSignal.timeout(8000)}),j=await r.json();health.api=!!(r.ok&&j.ok);health.cloud=!!j.cloudState}catch{health.api=false;health.cloud=false}renderHealth()}
window.addEventListener('online',()=>{health.online=true;checkHealth(true)});window.addEventListener('offline',()=>{health.online=false;renderHealth()});
function mobileNav(){let n=$('.v11-mobile-nav');if(n)return n;n=document.createElement('nav');n.className='v11-mobile-nav';n.setAttribute('aria-label','التنقل الرئيسي');const items=[['dashboard','الرئيسية'],['workforce','الموظفون'],['projects','المشاريع'],['tasks','المهام'],['reports','التقارير']];n.innerHTML=items.map(([id,l])=>`<button type="button" data-v11-view="${id}">${svg(id)}<span>${l}</span></button>`).join('');document.body.appendChild(n);n.addEventListener('click',e=>{const b=e.target.closest('[data-v11-view]');if(!b)return;const target=$(`[data-view="${b.dataset.v11View}"]`);target?.click();syncMobileNav()});syncMobileNav();return n}
function syncMobileNav(){const active=$('[data-view].active')?.dataset.view||'dashboard';$$('[data-v11-view]').forEach(b=>b.classList.toggle('active',b.dataset.v11View===active))}
function palette(){let root=$('.v11-command');if(root)return root;root=document.createElement('div');root.className='v11-command';root.innerHTML=`<div class="v11-palette" role="dialog" aria-modal="true" aria-label="الأوامر السريعة"><div class="v11-search">${svg('search')}<input autocomplete="off" placeholder="ابحث عن موظف، مشروع، مهمة أو أمر سريع..." aria-label="بحث سريع"><kbd>ESC</kbd></div><div class="v11-results"></div></div>`;document.body.appendChild(root);root.addEventListener('click',e=>{if(e.target===root)closePalette()});const input=root.querySelector('input');input.addEventListener('input',renderResults);input.addEventListener('keydown',e=>{if(e.key==='Enter'){root.querySelector('.v11-result')?.click()}else if(e.key==='Escape')closePalette()});return root}
function items(){const s=read(),out=[{t:'أمر سريع',d:'إنشاء مهمة مباشرة',i:'bolt',a:()=>document.querySelector('[data-v9-quick]')?.click()},{t:'المحلل المالي',d:'فتح مركز راكان للتحليل المالي والاستثماري',i:'finance',a:()=>window.NawafFinance?.open?.()},{t:'تطبيقاتي',d:'فتح مُعين وقدّها',i:'apps',a:()=>location.href='apps.html'}];for(const [id,l] of [['dashboard','الرئيسية'],['workforce','الموظفون'],['projects','المشاريع'],['tasks','المهام'],['reports','التقارير']])out.push({t:l,d:'فتح القسم',i:id,a:()=>document.querySelector(`[data-view="${id}"]`)?.click()});for(const e of s.employees||[])out.push({t:e.name,d:e.role||e.department||'موظف AI',i:'workforce',a:()=>document.querySelector(`[data-employee="${CSS.escape(e.id)}"]`)?.click()});for(const p of s.projects||[])out.push({t:p.name,d:`مشروع • ${p.phase||p.status||''}`,i:'projects',a:()=>document.querySelector(`[data-project="${CSS.escape(p.id)}"]`)?.click()});for(const t of (s.tasks||[]).slice(0,25))out.push({t:t.title,d:`مهمة • ${t.status||'READY'}`,i:'tasks',a:()=>document.querySelector(`[data-task="${CSS.escape(t.id)}"]`)?.click()});return out}
function renderResults(){const root=palette(),q=root.querySelector('input').value.trim().toLowerCase(),list=items().filter(x=>!q||(`${x.t} ${x.d}`).toLowerCase().includes(q)).slice(0,18),host=root.querySelector('.v11-results');host.innerHTML=list.length?list.map((x,i)=>`<button type="button" class="v11-result${i===0?' active':''}" data-index="${i}">${svg(x.i)}<span><b>${escapeHtml(x.t)}</b><small>${escapeHtml(x.d)}</small></span></button>`).join(''):'<div class="v11-empty">ما لقيت نتيجة مطابقة.</div>';host.querySelectorAll('[data-index]').forEach(b=>b.addEventListener('click',()=>{const x=list[Number(b.dataset.index)];closePalette();setTimeout(()=>x?.a?.(),30)}))}
function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function openPalette(){const p=palette();p.classList.add('show');p.querySelector('input').value='';renderResults();setTimeout(()=>p.querySelector('input').focus(),20)}function closePalette(){palette().classList.remove('show')}
function quickSearchButton(){if($('[data-v11-search]'))return;const actions=$('.v8-actions');if(!actions)return;const b=document.createElement('button');b.type='button';b.className='v8-btn v11-quick-search';b.setAttribute('data-v11-search','1');b.innerHTML=`${svg('search')}<span>بحث سريع</span>`;b.addEventListener('click',openPalette);actions.prepend(b)}
const errors=[];function addError(msg){const text=String(msg||'خطأ غير معروف').slice(0,500);if(errors[0]===text)return;errors.unshift(text);if(errors.length>8)errors.pop();let b=$('.v11-error-badge');if(!b){b=document.createElement('button');b.type='button';b.className='v11-error-badge';b.textContent='مشكلة تقنية';document.body.appendChild(b);b.onclick=()=>panel().classList.toggle('show')}b.classList.add('show');panel().innerHTML=`<b>آخر المشاكل التقنية</b>${errors.map(x=>`<div class="v11-error-item">${escapeHtml(x)}</div>`).join('')}`}
function panel(){let p=$('.v11-error-panel');if(!p){p=document.createElement('div');p.className='v11-error-panel';document.body.appendChild(p)}return p}
window.addEventListener('error',e=>addError(e.message||'JavaScript error'));window.addEventListener('unhandledrejection',e=>addError(e.reason?.message||e.reason||'Promise rejected'));
function preventDoubleSubmit(){document.addEventListener('submit',e=>{const b=e.target.querySelector('button[type="submit"]');if(!b||b.classList.contains('v11-busy'))return;b.classList.add('v11-busy');b.setAttribute('aria-busy','true');setTimeout(()=>{b.classList.remove('v11-busy');b.removeAttribute('aria-busy')},4000)},true)}
function enhanceA11y(){document.querySelectorAll('button:not([type])').forEach(b=>b.type='button');document.querySelectorAll('a[target="_blank"]').forEach(a=>{if(!a.rel.includes('noopener'))a.rel=(a.rel+' noopener noreferrer').trim()});document.documentElement.lang='ar'}
let timer;const obs=new MutationObserver(()=>{clearTimeout(timer);timer=setTimeout(()=>{mobileNav();syncMobileNav();quickSearchButton();enhanceA11y()},80)});
function boot(){healthEl();renderHealth();checkHealth(true);mobileNav();quickSearchButton();enhanceA11y();preventDoubleSubmit();obs.observe(document.body,{subtree:true,childList:true});setInterval(()=>checkHealth(false),30000);document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openPalette()}else if(e.key==='Escape')closePalette()})}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();window.NawafHQV11={checkHealth,openPalette,closePalette};
})();